INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('35e8f827-2acc-44d4-8c02-66de1f1f4c64','9','hidrosfera','published',0,161,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('35e8f827-2acc-44d4-8c02-66de1f1f4c64','ro','Iarna, un lac îngheață la suprafață, dar peștii supraviețuiesc în apa de dedesubt. Ce proprietate a apei explică acest lucru?','["Gheața, mai puțin densă decât apa de la +4 °C, plutește și izolează apa de sub ea.","Apa, odată înghețată, devine mai densă decât cea lichidă și se scufundă imediat la fund.","Sarea dizolvată în apa de la fund coboară punctul de îngheț și o ține lichidă.","Curenții calzi care urcă de pe fundul lacului topesc gheața de la suprafață."]','Gheața ocupă un volum mai mare și e mai puțin densă decât apa de la +4 °C, de aceea plutește. Pătura de gheață de la suprafață izolează apa de dedesubt, care rămâne lichidă — și viața continuă acolo.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('f51d9f48-caa2-44b0-88ee-c5e88beadd87','9','hidrosfera','published',1,162,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('f51d9f48-caa2-44b0-88ee-c5e88beadd87','ro','De ce, la munte, rocile se sfărâmă mai repede acolo unde apa pătrunde în crăpături și îngheață noaptea?','["Gheața formată în fisuri dizolvă chimic mineralele și macină încet roca dură.","Înghețând, apa își mărește volumul și, ca o pană, sfărâmă roca din interior.","Apa caldă se evaporă din crăpături și lasă săruri care rup pereții rocii.","Vântul puternic de creastă mută fragmentele de rocă dintr-un loc în altul."]','Apa care îngheață se dilată și apasă pe pereții crăpăturii ca o pană, până desface roca. Este dezagregarea prin îngheț-dezgheț, un proces fizic, nu chimic.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('e38b7ae2-02ad-48a9-961c-c6d8bcfd44c6','9','hidrosfera','published',2,163,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('e38b7ae2-02ad-48a9-961c-c6d8bcfd44c6','ro','Un submarin coboară de la suprafață (28 °C) până la 1.000 m adâncime, în zona caldă. De ce, sub un anumit nivel, temperatura apei rămâne aproape constantă?','["Apropierea de scoarța fierbinte a Pământului încălzește apa tot mai mult spre adânc.","Apa amestecă uniform căldura pe verticală, deci rămâne la 28 °C la orice adâncime.","Sub circa 500 m lumina solară nu mai încălzește apa, care rămâne la circa 2 °C.","Sub 1.000 m presiunea uriașă comprimă apa și îi ridică mult temperatura."]','Soarele încălzește doar pătura de la suprafață; sub circa 500 m razele nu mai ajung, iar temperatura scade la circa 2 °C și rămâne aproape neschimbată, indiferent de latitudine.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('aa89818f-e29f-4a94-8227-aa9950117ce6','9','hidrosfera','published',3,164,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('aa89818f-e29f-4a94-8227-aa9950117ce6','ro','Mareele ating valoarea maximă (flux puternic) de două ori pe lună. Când se întâmplă acest lucru?','["Când Luna și Soarele acționează în unghi drept față de Pământ, adică în cuadratură.","Când apa oceanului atinge cea mai mare salinitate din tot cursul lunii.","Când bat cel mai puternic vânturile permanente peste oceanul deschis.","Când Soarele, Luna și Pământul se așază în linie, la Lună nouă și Lună plină."]','Când Soarele, Luna și Pământul sunt aliniați (conjuncție sau opoziție, la Lună nouă și Lună plină), atracțiile lor se adună și marea urcă cel mai mult. Când sunt în unghi drept (cuadratură), mareea e minimă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('bc0aad02-a677-4fc8-ac9c-4c050f4067a4','9','hidrosfera','published',0,165,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('bc0aad02-a677-4fc8-ac9c-4c050f4067a4','ro','Două orașe se află la aceeași latitudine, pe țărmuri opuse ale unui ocean. Unul are ierni blânde, celălalt ierni aspre. Ce factor oceanic explică cel mai bine diferența?','["Un curent cald spală țărmul cu ierni blânde, iar un curent rece pe cel cu ierni aspre.","Salinitatea diferită a apei din dreptul celor două orașe le schimbă clima în timpul iernii.","Adâncimea diferită a oceanului din apropierea celor două orașe le încălzește aerul.","Culoarea diferită a apei mării face ca un oraș să primească mai multă căldură."]','Curenții oceanici mută căldura pe glob: un curent cald (ca al Golfului) încălzește țărmul spre care ajunge, dând ierni blânde, în timp ce un curent rece răcește țărmul opus.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('a020b2cc-3675-473f-8dbc-42ba2d988540','9','hidrosfera','published',1,166,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('a020b2cc-3675-473f-8dbc-42ba2d988540','ro','Pe hartă vezi o apă curgătoare mare, cu numeroși afluenți, care se varsă în mare printr-o deltă. Cum o numim și cum se numește suprafața de pe care își adună apa?','["Este un pârâu mic, iar suprafața întinsă de pe care își adună toată apa se numește cumpăna apelor.","Este un fluviu, iar suprafața de pe care își adună apa se numește bazin hidrografic.","Este un afluent, iar suprafața de pe care își adună apa se numește confluența.","Este un izvor, iar suprafața de pe care își adună apa se numește curs superior."]','Cea mai mare apă curgătoare, cu mulți afluenți și vărsare în mare printr-o deltă, este un fluviu. Toată suprafața de pe care își strânge apa prin afluenți se numește bazin hidrografic.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('5bb4e2bc-aee4-401b-8420-e7c3090bff3d','9','hidrosfera','published',2,167,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('5bb4e2bc-aee4-401b-8420-e7c3090bff3d','ro','De ce limita zăpezilor permanente este la circa 5.000 m la Ecuator, dar coboară până la 0 m la poli?','["Munții din zona ecuatorială sunt mult mai înalți decât cei din regiunile de la poli.","La poli cad mult mai multe precipitații, ploaie și ninsoare, decât la Ecuator.","La Ecuator e cald până la mari altitudini, așa că zăpada rezistă doar foarte sus.","La Ecuator zăpada conține mai multă sare și de aceea nu reușește să înghețe."]','Limita zăpezilor urcă acolo unde e cald. La Ecuator e cald până la altitudini mari, deci zăpada se menține numai foarte sus; la poli e frig chiar la nivelul mării, așa că limita coboară la 0 m.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('dbc4f040-b190-46f4-b0fa-7ee4c7a81c55','9','hidrosfera','published',3,168,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('dbc4f040-b190-46f4-b0fa-7ee4c7a81c55','ro','Pe hartă vezi două întinderi de apă sărată: una foarte mare, mărginită de continente, cealaltă mult mai mică, la marginea unui continent și legată de prima. Cum le numim?','["Prima este o mare, iar a doua un ocean mai mic legat de ea.","Amândouă sunt oceane, deosebite doar prin mărimea suprafeței lor.","Amândouă sunt mări, deosebite doar prin mărimea suprafeței lor.","Prima este un ocean, iar a doua o mare mai mică legată de el."]','Oceanul este întinderea foarte mare de apă sărată delimitată de continente; marea este o întindere mult mai mică, la marginea sau în interiorul uscatului, legată de ocean.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('0c442f4d-c190-4f7c-8921-58eb48b9f6fb','9','hidrosfera','published',0,169,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('0c442f4d-c190-4f7c-8921-58eb48b9f6fb','ro','Groapa Marianelor, punctul cel mai coborât de pe Terra (circa −11.022 m), se află în Oceanul Pacific. De ce tocmai aici apare acest record?','["Fiindcă Pacificul este cel mai întins și, totodată, cel mai afund dintre oceane.","Fiindcă Pacificul este cel mai mic ocean, iar apa lui apasă mai tare pe fundul lui.","Fiindcă Pacificul are cea mai mare salinitate dintre toate oceanele lumii.","Fiindcă Pacificul este singurul ocean acoperit de gheață la suprafață."]','Pacificul este cel mai mare și mai adânc ocean, așa că nu e de mirare că tot el adăpostește cel mai coborât punct de pe Terra, Groapa Marianelor.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('01693d58-ada6-4993-a6c0-af293c71a4cf','9','hidrosfera','published',1,170,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('01693d58-ada6-4993-a6c0-af293c71a4cf','ro','Marea Neagră este aproape complet închisă de uscat și se leagă de Oceanul Planetar doar printr-o strâmtoare îngustă. Ce tip de mare este, după poziție?','["O mare deschisă, larg unită cu oceanul pe o bună parte a țărmului ei.","O mare interioară (continentală), adânc pătrunsă în masa uscatului.","O mare interinsulară, așezată în spațiul dintre insulele unui arhipelag.","O mare mărginașă, despărțită de ocean printr-un lung șir de peninsule."]','O mare adânc pătrunsă în uscat și legată de ocean doar printr-o strâmtoare îngustă este o mare interioară (continentală), cum este Marea Neagră.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('0f38ef44-3b39-4a85-9d6d-cddb57b95f70','9','hidrosfera','published',2,171,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('0f38ef44-3b39-4a85-9d6d-cddb57b95f70','ro','O mare se întinde între trei continente — Europa, Africa și Asia — și le leagă țărmurile. Cum se clasifică ea după poziție?','["Mare interinsulară, situată în spațiul dintre insulele apropiate ale unui arhipelag.","Mare mărginașă, separată de ocean printr-un șir de peninsule și de insule.","Mare mediterană (intercontinentală), așezată între mari mase continentale.","Mare interioară, pătrunsă adânc în uscatul unui singur continent."]','O mare așezată între continente, care le leagă țărmurile, este o mare mediterană (intercontinentală). Se deosebește de marea interioară (într-un singur continent) și de cea mărginașă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('4b239ed7-ff8e-41e4-b22a-3bf0213c8ada','9','hidrosfera','published',3,172,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('4b239ed7-ff8e-41e4-b22a-3bf0213c8ada','ro','Salinitatea este de doar 5–6‰ în Marea Baltică, dar ajunge la 41‰ în Marea Roșie. Ce explică această diferență uriașă?','["Marea Baltică este cu mult mai adâncă decât Marea Roșie, motiv pentru care apa ei rămâne dulce.","Marea Roșie conține alge roșii care fabrică sare și o adaugă mereu în apă.","Marea Baltică rămâne înghețată tot timpul anului, iar gheața reține sarea.","În Baltica se varsă multe râuri și evaporația e slabă; Marea Roșie e caldă și închisă."]','Salinitatea depinde de raportul dintre evaporație și aportul de apă dulce. În Baltica se varsă multe râuri și evaporația e slabă, deci salinitate mică; Marea Roșie e caldă, secetoasă și închisă, deci salinitate mare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('bff00163-c4b6-450a-8409-abcbc33a3122','9','hidrosfera','published',0,173,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('bff00163-c4b6-450a-8409-abcbc33a3122','ro','Departe de țărm, în larg, apa oceanului pare albastră intensă, deși apa în sine este incoloră. Ce explică această culoare?','["Apa reflectă mai ales lumina albastră din razele Soarelui, împrăștiind-o.","Sarea dizolvată în apă îi dă acea culoare albastră intensă, mai ales în larg.","Adâncimea foarte mare face ca orice apă să pară albastră, indiferent de loc.","Curenții reci care vin din adânc colorează treptat apa în albastru intens."]','Apa este incoloră, dar reflectă și împrăștie mai ales radiațiile albastre din lumina solară, de aceea marea pare albastră. Algele și particulele în suspensie îi pot schimba nuanța.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('f3d6f08c-1818-4d24-a8f1-8195dbed1099','9','hidrosfera','published',1,174,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('f3d6f08c-1818-4d24-a8f1-8195dbed1099','ro','În larg se formează brusc un val uriaș care străbate tot oceanul și lovește un țărm îndepărtat cu forță distrugătoare. Ce fel de val este, cel mai probabil?','["Un val cu totul obișnuit, ridicat de vânturile puternice care bat peste ocean.","Un val stârnit de zguduirea fundului oceanic, numit popular „tsunami”.","O maree înaltă, adică ridicarea apei atrasă de Lună și de Soare.","Un curent oceanic cald care împinge apa cu putere spre țărmul opus."]','Un val care traversează un ocean întreg și lovește distrugător nu este produs de vânt (acela dă valuri locale), ci de o zguduire bruscă a fundului oceanic — este valul „tsunami”.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('30bf8fe2-96c8-439e-bc44-d78bd2cb1997','9','hidrosfera','published',2,175,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('30bf8fe2-96c8-439e-bc44-d78bd2cb1997','ro','Două râuri au aceeași lățime a albiei, dar unul curge mult mai repede decât celălalt. Care mărime descrie exact această diferență de rapiditate a curgerii?','["Debitul apei, cantitatea care trece printr-o secțiune în unitatea de timp.","Bazinul hidrografic, suprafața de pe care râul își adună toată apa.","Viteza apei, adică distanța parcursă de curent în unitatea de timp.","Cumpăna apelor, linia înaltă care desparte două bazine vecine."]','Rapiditatea curgerii este viteza — distanța parcursă de apă în unitatea de timp. Debitul este volumul de apă care trece printr-o secțiune, o mărime diferită.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('e7d95146-872d-4e1e-8757-58aca4e33401','9','hidrosfera','published',3,176,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('e7d95146-872d-4e1e-8757-58aca4e33401','ro','După ploi, nivelul unui râu crește periodic și apa acoperă lunca, fără pagube deosebite. În altă parte, o creștere bruscă din topirea zăpezii inundă zonele vecine, cu pagube mari. Cum numim cele două fenomene?','["Primul este o inundație obișnuită, iar al doilea o simplă revărsare fără urmări deosebite.","Amândouă sunt viituri la fel, deosebite doar prin locul în care se produc.","Primul este un afluent care crește, al doilea o confluență care se revarsă.","Primul e o revărsare periodică; al doilea, o inundație cu pagube, produsă de o viitură."]','Revărsarea este creșterea periodică a nivelului, când apa acoperă lunca fără pagube mari; inundația este o revărsare neregulată, cu pagube, provocată adesea de o viitură (creștere bruscă și puternică).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('cb319ded-0901-455b-a48f-3d86eeaea710','9','hidrosfera','published',0,177,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('cb319ded-0901-455b-a48f-3d86eeaea710','ro','Un râu mic se varsă într-un râu mai mare, chiar în locul unde acesta își schimbă ușor direcția. Cum se numesc râul mic și, respectiv, locul unirii lor?','["Râul mic este afluentul, iar locul unirii se numește confluență.","Râul mic este colectorul, iar locul unirii se numește izvor.","Râul mic e bazinul hidrografic, iar locul unirii e cumpăna apelor.","Râul mic este cursul superior, iar locul unirii e gura de vărsare."]','Râul mic care se varsă într-unul mai mare (colectorul) este afluentul, iar locul unde se unesc se numește confluență.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('2eadfef5-7365-4527-b980-25eeeaf54fc3','9','hidrosfera','published',1,178,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('2eadfef5-7365-4527-b980-25eeeaf54fc3','ro','Lacul Baikal ocupă o adâncitură formată prin mișcări ale scoarței terestre, nu prin acțiunea apei, gheții sau vântului. Ce tip de lac este și ce agent i-a săpat cuveta?','["Lac carstic, cu cuveta dizolvată în roci de către apă (agent extern).","Lac tectonic, cu cuveta creată de mișcările scoarței (agent intern).","Lac antropic, cu cuveta săpată și amenajată de om în trecut.","Lac litoral, cu cuveta închisă de valuri și de curenții mării."]','Cuveta săpată de mișcările scoarței înseamnă un agent intern: lacul este tectonic (ca Baikal sau Tanganyika). Lacurile carstice, litorale sau glaciare sunt create de agenți externi.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9dbc4672-8194-4fee-911f-fbcbc6ccdb57','9','hidrosfera','published',2,179,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9dbc4672-8194-4fee-911f-fbcbc6ccdb57','ro','Un lac ocupă o adâncitură săpată de un fost ghețar montan, iar altul s-a format într-o zonă de calcar dizolvat de apă. Cum se numesc cele două tipuri de lac?','["Primul este un lac vulcanic, format în crater; al doilea, un lac litoral, lângă țărmul mării.","Amândouă sunt lacuri tectonice, în adâncituri create de mișcările scoarței.","Primul e lac glaciar, în circuri și văi; al doilea, lac carstic, în roci dizolvate.","Primul e un iaz de irigații; al doilea, un heleșteu pentru piscicultură."]','Lacurile glaciare umplu circuri și văi săpate de foștii ghețari (Bâlea, Bucura); lacurile carstice apar în roci solubile, dizolvate de apă (Vărășoaia).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('a264ef10-6091-41fb-a6a6-25e1f48a1a73','9','hidrosfera','published',3,180,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('a264ef10-6091-41fb-a6a6-25e1f48a1a73','ro','În spatele unui baraj mare, construit de om pe un râu, s-a format un lac folosit pentru producerea energiei electrice. Ce tip de lac este, după origine?','["Lac natural de baraj, închis de o prăbușire naturală de teren.","Lac tectonic, așezat într-o adâncitură largă creată de mișcările scoarței.","Lac litoral (lagună), despărțit de mare printr-un cordon de nisip.","Lac antropic hidroenergetic, format prin bararea artificială a văii."]','Lacul din spatele unui baraj construit de om este antropic; cel folosit pentru energie electrică (ca Lacul Vidra) se numește hidroenergetic — spre deosebire de iazuri și heleștee.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('b04c910b-dd24-45c4-9450-be8b719ee19f','9','hidrosfera','published',2,181,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('b04c910b-dd24-45c4-9450-be8b719ee19f','ro','Un ghețar de munte are o zonă unde se strâng zăpada și gheața, urmată de o „limbă” care coboară pe vale, cărând și depunând materiale la margini. Cum se numesc aceste elemente?','["Zona de acumulare e un fiord, iar materialele depuse sunt aisberguri.","Zona de acumulare e banchiza, iar materialele depuse sunt calote de gheață.","Zona de acumulare e circul glaciar, iar materialele depuse sunt morene.","Zona de acumulare e un nevé, care nu cară și nu depune niciun material."]','Un ghețar de vale are o zonă de acumulare numită circul glaciar și o limbă care coboară pe pantă; materialele cărate și depuse de ghețar se numesc morene.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('89db62ef-4522-4c9e-99ee-019bda6eb893','9','hidrosfera','published',3,182,1784635848659,1784635848659);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('89db62ef-4522-4c9e-99ee-019bda6eb893','ro','Într-un sat, oamenii sapă o fântână și dau de apă la câțiva metri adâncime; nivelul ei urcă și coboară după cât de mult plouă. Ce fel de apă subterană au întâlnit?','["Apă captivă de mare adâncime, prinsă strâns între două strate impermeabile.","Apă termală, încălzită în adânc și ieșită singură la suprafață.","Apă arteziană, care țâșnește deasupra solului fără să fie pompată.","Apă freatică, prima pânză de apă subterană, aflată aproape de suprafață."]','Apa aflată aproape de suprafață, deasupra primului strat impermeabil, al cărei nivel urcă și coboară după ploi, este pânza freatică — cea care alimentează fântânile și izvoarele. Apele captive stau mai adânc, sub presiune; cele arteziene ies singure la suprafață.');
